"use client";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, BarChart3, Bell, CalendarDays, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Download, Eye, FileText, LayoutDashboard, LogOut, Menu, Moon, Plus, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Sun, TrendingUp, Users, WandSparkles, X, AlertTriangle, CheckCircle2, Pencil, LoaderCircle, BriefcaseBusiness, CalendarClock } from "lucide-react";
import type { Demand, Employee, State, Session, ShiftException, DemandType } from "@/lib/types";
import { capacity, buildCalendar, simulate } from "@/lib/engine";
import { typeCapacity, type TypeCapacity } from "@/lib/type-capacity";
import { AuthScreen } from "@/components/capacity/auth-screen";
import { DailyCapacity } from "@/components/capacity/daily-capacity";
import { AccessManager } from "@/components/capacity/access-manager";
import { ManagementDashboard, ExecutiveDashboard } from "@/components/capacity/dashboards";
import { isReservation } from "@/components/capacity/demand-workflow";
import { WeeklyCHGPlanning } from "@/components/capacity/weekly-chg-planning";
import { addDays, weekStart, zoned, dateAt } from "@/lib/time";
import { DemandForm, EmployeeForm, ExceptionForm, SettingsForm, UserForm } from "@/components/capacity/forms";

const STATUS: Record<string, string> = { requested: "Solicitada", planning: "Em planejamento", confirmed: "Confirmada", running: "Em execução", completed: "Concluída", cancelled: "Cancelada" };
const PRIORITY: Record<string, string> = { low: "Baixa", medium: "Média", high: "Alta", critical: "Crítica" };
const NAV = [{ id: "overview", label: "Visão geral", icon: LayoutDashboard }, { id: "calendar", label: "Calendário operacional", icon: CalendarDays }, { id: "demands", label: "Demandas", icon: FileText }, { id: "employees", label: "Colaboradores", icon: Users }, { id: "shifts", label: "Escalas", icon: CalendarClock }, { id: "client", label: "Portal do cliente", icon: BarChart3 }];
type Modal = { kind: "demand"; data?: Partial<Demand>; employeeId?: string } | { kind: "employee"; data?: Employee } | { kind: "exception"; data?: ShiftException } | { kind: "simulator" } | { kind: "user" } | null;
type ApiResponse = { state?: State; session?: Session; error?: string; issues?: { message: string }[] };
const number = (n: number, decimals = 0) => (Number.isFinite(n) ? n : 0).toLocaleString("pt-BR", { maximumFractionDigits: decimals });
const initials = (name: string) => name.split(" ").filter(Boolean).map(n => n[0]).slice(0, 2).join("");
const dateLabel = (date: string, options?: Intl.DateTimeFormatOptions) => new Date(`${date}T12:00:00`).toLocaleDateString("pt-BR", options || { day: "2-digit", month: "short" }).replace(" de ", " ").replace(".", "");
const timeLabel = (iso: string, tz: string) => new Date(iso).toLocaleTimeString("pt-BR", { timeZone: tz, hour: "2-digit", minute: "2-digit" });
const daysBetween = (start: string, end: string) => { const result: string[] = []; for (let d = start; d <= end && result.length < 93; d = addDays(d, 1)) result.push(d); return result; };

export default function Home() {
  const [data, setData] = useState<State | null>(null);
  const requestEpoch = useRef(0);
  const [session, setSession] = useState<Session | null>(null);
  const [page, setPage] = useState("overview");
  const [loading, setLoading] = useState(true);
  const [loginRequired, setLoginRequired] = useState(false);
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [modal, setModal] = useState<Modal>(null);
  const [sidebar, setSidebar] = useState(false);
  const [rangeStart, setRangeStart] = useState(() => weekStart(new Date().toLocaleDateString("en-CA", { timeZone: "America/Sao_Paulo" }), 1));
  const [rangeDays, setRangeDays] = useState(7);
  const [customEnd, setCustomEnd] = useState("");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [employeeFilter, setEmployeeFilter] = useState("");
  const [teamFilter, setTeamFilter] = useState("");
  const [typeFilter, setTypeFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [search, setSearch] = useState("");
  const [calendarMode, setCalendarMode] = useState("week");
  const [executive, setExecutive] = useState(false);
  const [settingsTab, setSettingsTab] = useState("rules");
  const rangeEnd = customEnd || addDays(rangeStart, rangeDays - 1);
  const effectiveEnd = page === "calendar" ? calendarMode === "day" ? rangeStart : calendarMode === "month" ? addDays(rangeStart, 29) : rangeEnd : rangeEnd;
  const movePeriod = (direction: number) => { const step = page === "calendar" && calendarMode === "day" ? 1 : page === "calendar" && calendarMode === "month" ? 30 : daysBetween(rangeStart, rangeEnd).length; setRangeStart(addDays(rangeStart, direction * step)); if (customEnd) setCustomEnd(addDays(customEnd, direction * step)); };
  const refresh = useCallback(async () => { const epoch = requestEpoch.current; try { const response = await fetch("/api/state", { cache: "no-store" }); if (epoch !== requestEpoch.current) return; if (response.status === 401) { setLoginRequired(true); setData(null); return; } const result = await response.json() as ApiResponse; if (epoch !== requestEpoch.current) return; if (!response.ok || !result.state || !result.session) throw new Error(result.error || "Não foi possível carregar a operação."); const incoming = result.state; setData(previous => previous && (previous.revision ?? 0) > (incoming.revision ?? 0) ? previous : incoming); setSession(result.session); if (result.session.role === "client") { setPage(current => ["overview", "calendar"].includes(current) ? current : "overview"); setModal(null); } setLoginRequired(false); setError(""); } catch (e) { if (epoch === requestEpoch.current) setError(e instanceof Error ? e.message : "Erro de conexão."); } finally { if (epoch === requestEpoch.current) setLoading(false); } }, []);
  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => {
    if (modal || loginRequired) return;
    const sync = () => { if (document.visibilityState === "visible") void refresh(); };
    window.addEventListener("focus", sync);
    document.addEventListener("visibilitychange", sync);
    return () => { window.removeEventListener("focus", sync); document.removeEventListener("visibilitychange", sync); };
  }, [refresh, modal, loginRequired]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(""), 4200); return () => clearTimeout(timer); }, [toast]);
  const mutate = async (entity: string, action: string, values: unknown) => { const response = await fetch("/api/mutate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ entity, action, data: values, revision: data?.revision }) }); const result = await response.json() as ApiResponse; if (!response.ok) { if (response.status === 409) await refresh(); throw new Error(result.issues?.length ? result.issues.map(i => i.message).join("\n") : result.error || "Não foi possível salvar."); } if (result.state) { const incoming = result.state; setData(previous => previous && (previous.revision ?? 0) > (incoming.revision ?? 0) ? previous : incoming); } else await refresh(); const savedDemand = entity === "demand" && action === "upsert" ? values as Demand : null; setToast(action === "delete" ? "Registro removido. Capacidade recalculada." : savedDemand && isReservation(savedDemand.status) ? "Reserva salva. As horas produtivas aparecem em Reservas; confirme a alocação para comprometer a capacidade oficial." : savedDemand && ["confirmed", "running", "completed"].includes(savedDemand.status) ? "Alocação confirmada. Horas comprometidas, livres e indicadores recalculados." : "Alterações salvas. Capacidade atualizada."); };
  const navigate = (id: string) => { if (session?.role === "client" && !["overview", "calendar"].includes(id)) return; setPage(id); setSidebar(false); setSearch(""); };
  const filtered = useMemo(() => {
    if (!data) return null;
    const employees = data.employees.filter(e => (!employeeFilter || e.id === employeeFilter) && (!teamFilter || e.team === teamFilter));
    const ids = new Set(employees.map(e => e.id));
    const scoped = Boolean(employeeFilter || teamFilter);
    return { ...data, employees, exceptions: data.exceptions.filter(e => ids.has(e.employeeId)), demands: data.demands.filter(d => (!typeFilter || d.type === typeFilter) && (!statusFilter || d.status === statusFilter) && (!scoped || d.allocations.some(a => ids.has(a.employeeId)))).map(d => { const allocations = d.allocations.filter(a => ids.has(a.employeeId)); return { ...d, allocations, required: scoped ? Math.min(d.required, Math.max(1, new Set(allocations.map(a => a.employeeId)).size)) : d.required }; }) };
  }, [data, employeeFilter, teamFilter, typeFilter, statusFilter]);
  const capacityState = useMemo(() => {
    if (!data || !filtered) return null;
    const ids = new Set(filtered.employees.map(e => e.id));
    const scoped = Boolean(employeeFilter || teamFilter);
    return { ...filtered, demands: data.demands.filter(d => !scoped || d.allocations.some(a => ids.has(a.employeeId))).map(d => { const allocations = d.allocations.filter(a => ids.has(a.employeeId)); return { ...d, allocations, required: scoped ? Math.min(d.required, Math.max(1, new Set(allocations.map(a => a.employeeId)).size)) : d.required }; }) };
  }, [data, filtered, employeeFilter, teamFilter]);
  const metrics = useMemo(() => capacityState ? capacity(capacityState, rangeStart, effectiveEnd) : null, [capacityState, rangeStart, effectiveEnd]);
  const typeMetrics = useMemo(() => capacityState ? typeCapacity(capacityState, rangeStart, effectiveEnd, typeFilter ? typeFilter as DemandType : undefined) : null, [capacityState, rangeStart, effectiveEnd, typeFilter]);
  const cells = useMemo(() => capacityState && page === "calendar" ? buildCalendar(capacityState, rangeStart, calendarMode === "day" ? rangeStart : calendarMode === "month" ? addDays(rangeStart, 29) : rangeEnd) : [], [capacityState, rangeStart, rangeEnd, page, calendarMode]);
  const writable = session?.role === "admin" && page !== "client";
  const admin = session?.role === "admin";
  const timezone = data?.settings.timezone || "America/Sao_Paulo";
  const displayName = (id: string) => { const e = data?.employees.find(e => e.id === id); return (page === "client" || session?.role === "client") && !data?.settings.clientShowNames ? e?.code || "Colaborador" : e?.name || "Colaborador"; };
  const showDetails = !((page === "client" || session?.role === "client") && !data?.settings.clientShowDetails);
  const demands = (filtered?.demands || []).filter(d => dateAt(new Date(Date.parse(d.end) - 1).toISOString(), timezone) >= rangeStart && dateAt(d.start, timezone) <= rangeEnd && (!search || `${d.code} ${d.title} ${d.project} ${d.requester}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()))).sort((a, b) => a.start.localeCompare(b.start));
  const newDemand = () => setModal({ kind: "demand", data: { date: rangeStart } });
  const exportUrl = `/api/export?format=xlsx&from=${rangeStart}&to=${effectiveEnd}&type=${encodeURIComponent(typeFilter)}&status=${encodeURIComponent(statusFilter)}&employee=${encodeURIComponent(employeeFilter)}&team=${encodeURIComponent(teamFilter)}`;
  if (loginRequired) return <AuthScreen onLogin={refresh} />;
  if (loading || !data || !filtered || !metrics || !typeMetrics) return <div className="startup"><div className="brand-symbol"><span /><span /><span /><span /></div><h1>Capacity Manager</h1>{loading ? <><LoaderCircle className="spin" size={24} /><p>Preparando sua operação…</p></> : <><p className="error-text">{error || "Não foi possível carregar os dados."}</p><button className="button primary" onClick={() => { setLoading(true); refresh(); }}>Tentar novamente</button></>}</div>;
  const isExecutive = executive || page === "client" || session?.role === "client";
  const title = page === "settings" ? "Configurações" : NAV.find(n => n.id === page)?.label || "Visão geral";
  const activeFilters = [employeeFilter, teamFilter, typeFilter, statusFilter].filter(Boolean).length;
  const occupation = typeMetrics.occupancy || 0;
  const health = typeMetrics.confirmed <= 0 || typeMetrics.deficit > 0 || occupation > data.settings.saturationThreshold ? "danger" : occupation >= data.settings.comfortableThreshold ? "warning" : "healthy";
  return <div className="app-shell">
    {sidebar && <button className="sidebar-backdrop" aria-label="Fechar navegação" onClick={() => setSidebar(false)} />}
    <aside className={`sidebar ${sidebar ? "open" : ""}`}>
      <a className="brand spread-brand" href="#" onClick={e => { e.preventDefault(); navigate("overview"); }}><img src="/spread-logo-white.svg" alt="Spread" /><span>Capacity Manager</span></a>
      <div className="workspace"><div className="workspace-icon"><BriefcaseBusiness size={16} /></div><div>Operações Spread<small>Gestão de capacidade</small></div><span className="workspace-dot" /></div>
      <div className="nav-caption">PLANEJAMENTO</div>
      <nav>{NAV.filter(n => session?.role !== "client" || ["overview", "calendar"].includes(n.id)).map(n => <button key={n.id} className={`nav-item ${page === n.id ? "active" : ""}`} onClick={() => navigate(n.id)}><n.icon size={18} strokeWidth={1.7} /><span>{n.label}</span>{n.id === "demands" && <span className="nav-count">{data.demands.filter(d => !["cancelled", "completed"].includes(d.status)).length}</span>}{page === n.id && <span className="nav-active-dot" />}</button>)}</nav>
      {admin && <><div className="nav-caption administration">ADMINISTRAÇÃO</div><button className={`nav-item ${page === "settings" ? "active" : ""}`} onClick={() => navigate("settings")}><Settings2 size={18} strokeWidth={1.7} /><span>Configurações</span></button></>}
      <div className="sidebar-bottom">{session?.role !== "client" ? <div className="planning-tip"><span className="tip-icon"><Sparkles size={16} /></span><strong>Antecipe o próximo passo.</strong><p>Simule novas demandas e planeje com mais segurança.</p><button onClick={() => setModal({ kind: "simulator" })}>Explorar simulador <ArrowUpRight size={14} /></button></div> : <div className="planning-tip consultation-tip"><Eye size={20} /><strong>Visibilidade para decidir.</strong><p>Consulte a capacidade real e as demandas confirmadas da operação.</p><span className="consultation-tip-label">Acesso de consulta</span></div>}<div className="sidebar-user"><span className="avatar user-avatar">{initials(session?.name || "Gestor")}</span><div><strong>{session?.name || "Gestor"}</strong><small>{session?.role === "admin" ? "Administrador" : session?.role === "client" ? "Consulta · somente leitura" : "Gestor de operações"}</small></div><button className="icon-button" aria-label="Sair da conta" title="Sair da conta" onClick={async () => { requestEpoch.current += 1; await fetch("/api/auth", { method: "DELETE" }); setSession(null); setData(null); setModal(null); setPage("overview"); setLoginRequired(true); }}><LogOut size={15} /></button></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-toggle" onClick={() => setSidebar(true)} aria-label="Abrir navegação"><Menu size={20} /></button><span>Workspace</span><ChevronRight size={13} /><strong>{title}</strong></div><div className="topbar-right"><span className="environment-tag"><span /> Ambiente operacional</span><span className="topbar-divider" />{session?.role === "admin" && <button className="icon-button notification" title="Ver pendências de planejamento" aria-label="Ver pendências" onClick={() => { setPage("overview"); setExecutive(false); setTimeout(() => document.getElementById("attention-panel")?.scrollIntoView({ behavior: "smooth", block: "center" }), 50); }}><Bell size={19} />{(metrics.issues.length > 0 || metrics.uncovered > 0) && <i />}</button>}<span className="avatar small-avatar">{initials(session?.name || "Gestor")}</span></div></header>
      <main className="content">
        <section className="page-heading"><div><div className="eyebrow">{page === "overview" ? "SEU CENTRO DE PLANEJAMENTO" : page === "client" ? "TRANSPARÊNCIA PARA DECIDIR" : "GESTÃO DE CAPACIDADE"}</div><h1>{page === "overview" ? "Uma visão clara da sua capacidade." : page === "calendar" ? "Cada pessoa, no tempo certo." : page === "demands" ? "Demandas da operação" : page === "employees" ? "As pessoas por trás da operação." : page === "shifts" ? "Escalas e jornadas" : page === "client" ? "Capacidade para o próximo passo." : "Uma operação do seu jeito."}</h1><p>{page === "overview" ? "Conecte pessoas, demandas e disponibilidade. Planeje com confiança." : page === "calendar" ? "Acompanhe alocações, disponibilidade e descanso hora a hora." : page === "demands" ? "Organize o trabalho e acompanhe cada alocação, do planejamento à entrega." : page === "employees" ? "Gerencie sua equipe, jornadas e elegibilidade para novas escalas." : page === "shifts" ? "Planeje exceções, folgas e ativações extraordinárias com segurança." : page === "client" ? "Visibilidade sobre a operação. Clareza sobre o que vem a seguir." : "Regras parametrizáveis para refletir a realidade da sua equipe."}</p></div><div className="heading-actions">{writable && ["overview", "client", "calendar"].includes(page) && <button className="button secondary" onClick={() => setModal({ kind: "simulator" })}><WandSparkles size={16} /> Simular demanda</button>}{writable && page !== "settings" && (page !== "employees" || admin) && <button className="button primary" onClick={() => page === "employees" ? setModal({ kind: "employee" }) : page === "shifts" ? setModal({ kind: "exception" }) : newDemand()}><Plus size={17} />{page === "employees" ? "Novo colaborador" : page === "shifts" ? "Nova escala" : "Nova demanda"}</button>}</div></section>
        <section className="toolbar"><div className="period-controls"><button className="button period-button" onClick={() => { setRangeStart(weekStart(dateAt(new Date().toISOString(), timezone), data.settings.weekStartsOn)); setRangeDays(7); setCustomEnd(""); }}><CalendarDays size={16} /> Esta semana <ChevronDown size={13} /></button><div className="date-navigator"><button aria-label="Período anterior" onClick={() => movePeriod(-1)}><ChevronLeft size={16} /></button><span>{dateLabel(rangeStart)} <span className="range-dash">—</span> {dateLabel(effectiveEnd)}<small>{rangeStart.slice(0, 4)}</small></span><button aria-label="Próximo período" onClick={() => movePeriod(1)}><ChevronRight size={16} /></button></div><select aria-label="Horizonte de planejamento" value={customEnd ? "custom" : rangeDays} onChange={e => { if (e.target.value === "custom") setCustomEnd(addDays(rangeStart, 6)); else { setRangeDays(Number(e.target.value)); setCustomEnd(""); } }}><option value={7}>7 dias</option><option value={14}>14 dias</option><option value={30}>30 dias</option><option value="custom">Personalizado</option></select></div><div className="toolbar-actions"><button className={`button filter-button ${activeFilters || filtersOpen ? "selected" : ""}`} onClick={() => setFiltersOpen(!filtersOpen)}><SlidersHorizontal size={15} /> Filtros{activeFilters > 0 && <span className="filter-count">{activeFilters}</span>}</button>{session?.role !== "client" && <a className="button export-button" href={exportUrl}><ArrowDownToLine size={15} /><span>Exportar</span></a>}</div></section>
        {(filtersOpen || customEnd) && <div className="filter-panel">{customEnd && <><Field label="Data inicial"><input type="date" value={rangeStart} onChange={e => setRangeStart(e.target.value)} /></Field><Field label="Data final"><input type="date" min={rangeStart} value={customEnd} onChange={e => setCustomEnd(e.target.value)} /></Field></>}{filtersOpen && <><Field label="Colaborador"><select value={employeeFilter} onChange={e => setEmployeeFilter(e.target.value)}><option value="">Todos os colaboradores</option>{data.employees.map(e => <option key={e.id} value={e.id}>{displayName(e.id)}</option>)}</select></Field><Field label="Equipe"><select value={teamFilter} onChange={e => setTeamFilter(e.target.value)}><option value="">Todas as equipes</option>{Array.from(new Set(data.employees.map(e => e.team))).map(t => <option key={t}>{t}</option>)}</select></Field><Field label="Tipo de demanda"><select value={typeFilter} onChange={e => setTypeFilter(e.target.value)}><option value="">Todos os tipos</option>{["BSIM", "TSD", "CHG"].map(t => <option key={t}>{t}</option>)}</select></Field><Field label="Status"><select value={statusFilter} onChange={e => setStatusFilter(e.target.value)}><option value="">Todos os status</option>{Object.entries(STATUS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></Field>{activeFilters > 0 && <button className="text-button" onClick={() => { setEmployeeFilter(""); setTeamFilter(""); setTypeFilter(""); setStatusFilter(""); }}>Limpar filtros</button>}</>}</div>}
        {["overview", "calendar", "client"].includes(page) && <section className="type-filter-bar" aria-label="Filtro por tipo de demanda"><div><span className="type-filter-label">Tipo de demanda</span><div className="type-filter-options">{[["", "Todos os tipos"], ["BSIM", "BSIM"], ["TSD", "TSD"], ["CHG", "CHG"]].map(([value, label]) => <button key={value} className={typeFilter === value ? "active" : ""} aria-pressed={typeFilter === value} onClick={() => setTypeFilter(value)}>{value && <span className={`dot ${value.toLowerCase()}`} />}{label}</button>)}</div></div><span className="type-filter-description">{typeFilter === "CHG" ? <><Moon size={17} /> Janela CHG: {data.settings.nightStart} — {data.settings.nightEnd}</> : <><ShieldCheck size={17} /> Somente jornadas aprovadas geram capacidade confirmada</>}</span></section>}
        {(typeFilter || statusFilter) && <div className="capacity-scope-note"><ShieldCheck size={15} /> Todos os compromissos continuam ocupando a agenda. O filtro de tipo mostra as janelas realmente aptas à atividade selecionada.</div>}
        {(page === "overview" || page === "client") && <>
          <div className="view-tabs">{session?.role === "client" ? <span className="consultation-label"><Eye size={16} /> Visão de consulta <span>Somente leitura</span></span> : <div className="segmented dashboard-switch" role="tablist" aria-label="Visão do dashboard"><button id="management-tab" role="tab" aria-selected={!isExecutive} aria-controls="dashboard-content" className={!isExecutive ? "active" : ""} onClick={() => { if (page === "client") navigate("overview"); setExecutive(false); }}><LayoutDashboard size={15} /> Visão gerencial</button><button id="executive-tab" role="tab" aria-selected={isExecutive} aria-controls="dashboard-content" className={isExecutive ? "active" : ""} onClick={() => setExecutive(true)}><TrendingUp size={15} /> Visão executiva</button></div>}<span className="live-indicator"><span /> Dados da operação atualizados</span></div>
          <div id="dashboard-content" role="tabpanel" aria-labelledby={isExecutive ? "executive-tab" : "management-tab"}>
            {isExecutive ? <ExecutiveDashboard state={capacityState!} metrics={metrics} typed={typeMetrics} from={rangeStart} to={effectiveEnd} type={typeFilter as DemandType || undefined} writable={writable} displayName={displayName} onDemand={demand => setModal({ kind: "demand", data: data.demands.find(original => original.id === demand.id) || demand })} onNavigate={navigate} onSimulate={() => setModal({ kind: "simulator" })} /> : <ManagementDashboard state={capacityState!} metrics={metrics} typed={typeMetrics} from={rangeStart} to={effectiveEnd} type={typeFilter as DemandType || undefined} writable={writable} displayName={displayName} onDemand={demand => setModal({ kind: "demand", data: data.demands.find(original => original.id === demand.id) || demand })} onNavigate={navigate} onSimulate={() => setModal({ kind: "simulator" })} />}
          </div>
        </>}
        {page === "calendar" && typeFilter === "CHG" && <WeeklyCHGPlanning metrics={typeMetrics} from={rangeStart} to={effectiveEnd} />}
        {page === "calendar" && <TypeCapacityBanner metrics={typeMetrics} type={typeFilter as DemandType || undefined} nightStart={data.settings.nightStart} nightEnd={data.settings.nightEnd} writable={writable} onSimulate={() => setModal({ kind: "simulator" })} />}
        {page === "calendar" && <section className="card calendar-card"><div className="card-heading"><div><h2>Mapa de capacidade</h2><p>{filtered.employees.filter(e => e.active).length} colaboradores · {timezone} · horários de 00h a 23h</p></div><div className="segmented">{[["day", "Dia"], ["week", "Semana"], ["month", "Mês"]].map(([id, label]) => <button key={id} className={calendarMode === id ? "active" : ""} onClick={() => setCalendarMode(id)}>{label}</button>)}</div></div><div className="calendar-legend">{[["free", "Disponível"], ["BSIM", "BSIM"], ["TSD", "TSD"], ["CHG", "CHG"], ["reservation", "Reserva"], ["potential", "Potencial extraordinário"], ["off", "Fora da jornada"], ["rest", "Descanso obrigatório"], ["conflict", "Conflito / ausência"]].map(([key, label]) => <span key={key}><i className={`legend-square slot-${key}`} />{label}</span>)}</div><CalendarGrid data={capacityState!} typeFilter={typeFilter} statusFilter={statusFilter} cells={cells} start={rangeStart} end={calendarMode === "day" ? rangeStart : calendarMode === "month" ? addDays(rangeStart, 29) : rangeEnd} mode={calendarMode} displayName={displayName} onCell={(employeeId, date, hour, demandId) => { if (demandId) { const demand = data.demands.find(d => d.id === demandId); if (demand) setModal({ kind: "demand", data: demand }); } else if (writable) setModal({ kind: "demand", employeeId, data: { date, type: typeFilter as DemandType || "BSIM", start: zoned(date, `${String(hour).padStart(2, "0")}:00`, timezone), end: zoned(hour === 23 ? addDays(date, 1) : date, `${String((hour + 1) % 24).padStart(2, "0")}:00`, timezone) } }); }} /><div className="calendar-hint"><CircleHelp size={15} /><span>{writable ? "Clique em uma faixa horária para alocar uma demanda. Passe o cursor para consultar disponibilidade, bloqueios e retorno permitido." : "Passe o cursor para consultar a disponibilidade e as alocações da operação."}</span></div></section>}
        {["overview", "calendar", "client"].includes(page) && <DailyCapacity metrics={typeMetrics} type={typeFilter as DemandType || undefined} timezone={timezone} nightStart={data.settings.nightStart} nightEnd={data.settings.nightEnd} displayName={displayName} onDemand={demand => setModal({ kind: "demand", data: data.demands.find(original => original.id === demand.id) || demand })} />}
        {page === "demands" && <section className="card full-table"><div className="card-heading"><div><h2>Demandas no período <span className="count-pill">{demands.length}</span></h2><p>{number(metrics.reserved, 1)}h em planejamento · {number(metrics.committed, 1)}h confirmadas</p></div><div className="search-input"><Search size={16} /><input aria-label="Buscar demandas" placeholder="Buscar código, demanda ou projeto" value={search} onChange={e => setSearch(e.target.value)} /></div></div><DemandTable demands={demands} data={data} timezone={timezone} displayName={displayName} showDetails={showDetails} onOpen={d => setModal({ kind: "demand", data: data.demands.find(original => original.id === d.id) || d })} detailed /><div className="table-footer"><span>{demands.length} registro(s) no período selecionado</span><span>Reservas não consomem capacidade confirmada</span></div></section>}
        {page === "employees" && <><div className="compact-stats"><div><Users size={18} /><span><strong>{data.employees.filter(e => e.active).length}</strong> colaboradores ativos</span></div><div><Sun size={18} /><span><strong>{data.employees.filter(e => e.journey === "day" && e.active).length}</strong> em jornada diurna</span></div><div><Moon size={18} /><span><strong>{data.employees.filter(e => e.journey === "night" && e.active).length}</strong> em jornada noturna</span></div><div><Sparkles size={18} /><span><strong>{metrics.eligibleNight}</strong> elegíveis no período</span></div></div><section className="card full-table"><div className="card-heading"><div><h2>Equipe operacional</h2><p>Jornadas recorrentes e limites individuais</p></div><div className="search-input"><Search size={16} /><input aria-label="Buscar colaboradores" placeholder="Buscar colaborador" value={search} onChange={e => setSearch(e.target.value)} /></div></div><div className="table-scroll"><table><thead><tr><th>COLABORADOR</th><th>EQUIPE / FUNÇÃO</th><th>JORNADA</th><th>CARGA SEMANAL</th><th>EXTRA NOTURNA</th><th>STATUS</th><th /></tr></thead><tbody>{filtered.employees.filter(e => `${e.name} ${e.code} ${e.team}`.toLowerCase().includes(search.toLowerCase())).map((e, i) => <tr key={e.id} onClick={() => setModal({ kind: "employee", data: e })} className="clickable-row"><td><div className="person"><span className={`avatar color-${i % 5}`}>{initials(e.name)}</span><span><strong>{e.name}</strong><small>{e.code}</small></span></div></td><td><strong>{e.team}</strong><small>{e.role}</small></td><td><span className="journey-label">{e.journey === "night" ? <Moon size={14} /> : <Sun size={14} />}{e.startTime} — {e.endTime}</span><small>{e.weekdays.map(d => ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"][d % 7]).join(" · ")}</small></td><td><strong>{e.weeklyHours}h</strong><small>Limite de {e.weeklyLimit}h</small></td><td><span className={`badge ${e.eligibleNight ? "confirmed" : "muted"}`}>{e.eligibleNight ? `${e.maxExtraNights} / semana` : "Não elegível"}</span></td><td><span className={`status-dot ${e.active ? "green" : "gray"}`} />{e.active ? "Ativo" : "Inativo"}</td><td><Pencil size={15} className="muted-icon" /></td></tr>)}</tbody></table></div></section></>}
        {page === "shifts" && <><div className="info-banner"><ShieldCheck size={20} /><div><strong>As regras acompanham cada escala.</strong><p>Jornadas recorrentes são definidas no cadastro de colaboradores. Use exceções para alterar horários, registrar ausências ou aprovar uma ativação extraordinária.</p></div><button className="text-button" onClick={() => navigate("employees")}>Jornadas recorrentes <ArrowUpRight size={15} /></button></div><section className="card full-table"><div className="card-heading"><div><h2>Escalas e exceções por data</h2><p>Uma escala extraordinária representa uma ativação, mesmo com várias demandas</p></div></div><div className="table-scroll"><table><thead><tr><th>COLABORADOR</th><th>DATA</th><th>TIPO</th><th>HORÁRIO</th><th>JUSTIFICATIVA</th><th>APROVAÇÃO</th><th /></tr></thead><tbody>{filtered.exceptions.filter(e => e.date >= rangeStart && e.date <= rangeEnd).sort((a, b) => a.date.localeCompare(b.date)).map(e => <tr className="clickable-row" key={e.id} onClick={() => setModal({ kind: "exception", data: e })}><td><strong>{displayName(e.employeeId)}</strong></td><td>{dateLabel(e.date, { day: "2-digit", month: "short", weekday: "short" })}</td><td><span className={`badge ${e.kind === "extra" ? "chg" : "muted"}`}>{{ off: "Folga", vacation: "Férias", absence: "Ausência", holiday: "Feriado", override: "Ajuste de jornada", extra: "Extraordinária noturna" }[e.kind]}</span></td><td>{e.startTime && e.endTime ? `${e.startTime} — ${e.endTime}${e.endTime <= e.startTime ? " (+1 dia)" : ""}` : "Dia completo"}</td><td className="note-cell">{e.note || "—"}</td><td><span className={`badge ${e.approved ? "confirmed" : "planning"}`}>{e.approved ? "Aprovada" : "Pendente"}</span></td><td><Pencil size={15} className="muted-icon" /></td></tr>)}</tbody></table>{!filtered.exceptions.some(e => e.date >= rangeStart && e.date <= rangeEnd) && <Empty icon={CalendarClock} title="Nenhuma exceção neste período" text="A operação segue as jornadas recorrentes. Cadastre uma escala para ajustar o planejamento." />}</div></section><section className="card night-roster"><div className="card-heading"><div><h2>Escala noturna da semana</h2><p>Jornadas fixas e ativações aprovadas por data de início</p></div><Moon size={19} /></div><div className="roster-grid">{daysBetween(rangeStart, rangeEnd).map(date => { const fixed = filtered.employees.filter(e => e.active && e.journey === "night" && e.weekdays.includes(new Date(date + "T12:00:00").getDay() || 7) && !filtered.exceptions.some(x => x.employeeId === e.id && x.date === date && x.approved && ["off", "vacation", "absence", "holiday"].includes(x.kind))); const extras = filtered.exceptions.filter(e => e.date === date && e.kind === "extra" && e.approved); return <div key={date}><span>{dateLabel(date, { weekday: "short" })}</span><strong>{dateLabel(date)}</strong>{fixed.map(e => <p key={e.id}><i className="dot teal" />{displayName(e.id)}<small>{e.startTime} — {e.endTime}</small></p>)}{extras.map(e => <p key={e.id}><i className="dot chg" />{displayName(e.employeeId)}<small>{e.startTime} — {e.endTime}</small></p>)}{!fixed.length && !extras.length && <small className="uncovered-label">Sem escala confirmada</small>}{writable && <button className="roster-add" onClick={() => setModal({ kind: "exception", data: { id: "", employeeId: "", date, kind: "extra", approved: true, startTime: data.settings.nightStart, endTime: data.settings.nightEnd } })}><Plus size={13} /> Escalar</button>}</div>; })}</div></section></>}
        {page === "settings" && admin && <section className="card settings-card"><div className="settings-tabs"><button className={settingsTab === "rules" ? "active" : ""} onClick={() => setSettingsTab("rules")}><Settings2 size={17} /> Regras da operação</button><button className={settingsTab === "privacy" ? "active" : ""} onClick={() => setSettingsTab("privacy")}><Eye size={17} /> Consulta e privacidade</button><button className={settingsTab === "users" ? "active" : ""} onClick={() => setSettingsTab("users")}><ShieldCheck size={17} /> Acessos e histórico</button></div>{settingsTab === "users" ? <div className="settings-content"><AccessManager sessionId={session!.id} onSave={value => mutate("user", "upsert", value)} /><h2 className="audit-title">Histórico de alterações</h2><div className="audit-list">{(data.audit || []).slice().reverse().slice(0, 30).map(a => <div key={a.id}><span className="audit-dot" /><div><strong>{a.actor}</strong><p>{a.action} · {a.entity}</p></div><small>{new Date(a.at).toLocaleString("pt-BR", { timeZone: timezone })}</small></div>)}{!data.audit?.length && <p className="muted-copy">As alterações na operação serão registradas aqui.</p>}</div></div> : <SettingsForm data={data.settings} privacy={settingsTab === "privacy"} onSave={v => mutate("settings", "upsert", v)} />}</section>}
        <footer className="page-footer"><span><span className="footer-mark" /> Capacity Manager <span className="footer-separator">/</span> Planejamento que gera confiança.</span><span><span className="dot green" /> Operação conectada <span className="footer-separator">·</span> {timezone}</span></footer>
      </main>
    </div>
    {toast && <div className="toast"><CheckCircle2 size={18} />{toast}<button aria-label="Fechar notificação" onClick={() => setToast("")}><X size={15} /></button></div>}
    {modal && (session?.role === "admin" || modal.kind === "demand") && <ModalShell title={modal.kind === "demand" ? modal.data?.id ? "Detalhes da demanda" : "Nova demanda" : modal.kind === "employee" ? modal.data?.id ? "Editar colaborador" : "Novo colaborador" : modal.kind === "exception" ? modal.data?.id ? "Editar escala ou exceção" : "Nova escala ou exceção" : modal.kind === "user" ? "Criar acesso" : "Simulador de absorção"} subtitle={modal.kind === "simulator" ? "Explore a capacidade sem alterar o planejamento oficial." : modal.kind === "demand" ? "Cada alocação é validada contra jornadas, descanso e limites." : "As alterações recalculam automaticamente a capacidade."} onClose={() => setModal(null)} wide={modal.kind === "demand" || modal.kind === "simulator"}>
      {modal.kind === "demand" && <DemandForm data={modal.data} employeeId={modal.employeeId} state={data} readonly={!writable} displayName={displayName} showDetails={showDetails && session?.role === "admin"} onSave={async v => { await mutate("demand", "upsert", v); setModal(null); }} onDelete={async v => { await mutate("demand", "delete", v); setModal(null); }} />}
      {modal.kind === "employee" && <EmployeeForm data={modal.data} readonly={!admin} onSave={async v => { await mutate("employee", "upsert", v); setModal(null); }} onDelete={async v => { await mutate("employee", "delete", v); setModal(null); }} />}
      {modal.kind === "exception" && <ExceptionForm data={modal.data} state={data} readonly={!writable} onSave={async v => { await mutate("exception", "upsert", v); setModal(null); }} onDelete={async v => { await mutate("exception", "delete", v); setModal(null); }} />}
      {modal.kind === "simulator" && <Simulator data={data} start={rangeStart} displayName={displayName} writable={writable} onCreate={proposal => setModal({ kind: "demand", data: proposal })} />}
      {modal.kind === "user" && <UserForm onSave={async v => { await mutate("user", "upsert", v); setModal(null); }} />}
    </ModalShell>}
  </div>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function TypeCapacityBanner({ metrics, type, nightStart, nightEnd, writable, onSimulate }: { metrics: TypeCapacity; type?: DemandType; nightStart: string; nightEnd: string; writable: boolean; onSimulate: () => void }) {
  return <div className="type-capacity-summary"><div className={`capacity-banner ${metrics.canAccept ? "healthy" : "warning"}`}><span className="banner-icon">{metrics.canAccept ? <CheckCircle2 size={23} /> : <Clock3 size={23} />}</span><div><strong>{metrics.canAccept ? `Capacidade confirmada${type ? ` para ${type}` : ""}: ${number(metrics.free, 2)}h livres` : `Sem capacidade confirmada${type ? ` para ${type}` : ""} no período`}</strong><p>{type === "CHG" ? `Somente horas aprovadas dentro da janela ${nightStart}–${nightEnd}, após pausas, descanso e compromissos.` : "Horas produtivas aprovadas, após pausas, ausências, descanso e compromissos."} {writable ? "Simule o horário e a quantidade de pessoas antes de confirmar." : "Consulte as janelas e as demandas confirmadas de cada dia na tabela abaixo."}</p></div>{writable && <button onClick={onSimulate}>Simular demanda <ArrowRight size={17} /></button>}</div>{metrics.potential > 0 && <div className="extra-potential-summary"><Moon size={17} /><strong>{number(metrics.potential, 2)}h de potencial extraordinário</strong><span>Capacidade condicionada à aprovação de escala e às regras de descanso. Não está somada às horas confirmadas.</span></div>}</div>;
}
function Metric({ title, value, suffix, icon: Icon, note, color, positive, progress, health }: { title: string; value: string; suffix: string; icon: typeof Users; note: string; color: string; positive?: boolean; progress?: number; health?: string }) { return <section className={`card metric-card metric-${color}`}><div className="metric-top"><span>{title}</span><span className={`metric-icon ${color}`}><Icon size={18} strokeWidth={1.8} /></span></div><div className="metric-value">{value}<span>{suffix}</span>{positive && <span className="available-pill">Disponível <ArrowUpRight size={11} /></span>}</div>{progress !== undefined && <div className={`metric-progress ${health}`}><span style={{ width: `${Math.min(100, progress)}%` }} /></div>}<p>{positive ? <span className="dot green" /> : progress === undefined ? <span className="metric-note-dash" /> : <span className={`dot ${health === "healthy" ? "green" : "amber"}`} />}{note}</p></section>; }
function CapacityChart({ daily }: { daily: { date: string; confirmed: number; committed: number; free: number; reserved: number; deficit: number }[] }) { const ceiling = Math.ceil(Math.max(8, ...daily.map(d => Math.max(d.confirmed, d.committed))) / 8) * 8; return <div className="capacity-chart"><div className="chart-y">{[1, .75, .5, .25, 0].map(n => <span key={n}>{number(ceiling * n)}h</span>)}</div><div className="chart-plot"><div className="chart-grid-lines">{[0, 1, 2, 3, 4].map(n => <span key={n} />)}</div><div className="chart-bars">{daily.map(d => <div className="chart-day" key={d.date}><div className="chart-bar-space" title={`${dateLabel(d.date)}: ${number(d.committed, 1)}h comprometidas, ${number(d.free, 1)}h livres, ${number(d.reserved, 1)}h em reservas`}><div className="chart-bar" style={{ height: `${Math.max(1, Math.max(d.confirmed, d.committed) / ceiling * 100)}%` }}><div className="bar-free" style={{ flex: Math.max(0, d.free) }} /><div className="bar-committed" style={{ flex: Math.max(0, d.committed) }} />{d.confirmed === 0 && d.committed === 0 && <div className="bar-empty" />}</div></div><div className="chart-day-label"><strong>{dateLabel(d.date, { weekday: "short" })}</strong><small>{dateLabel(d.date, { day: "2-digit", month: "2-digit" })}</small></div></div>)}</div></div></div>; }
function Donut({ byType, total }: { byType: Record<string, number>; total: number }) { const sum = (byType.BSIM || 0) + (byType.TSD || 0) + (byType.CHG || 0); const b = sum ? (byType.BSIM || 0) / sum * 100 : 0; const t = sum ? (byType.TSD || 0) / sum * 100 : 0; return <div className="donut-wrap"><div className="donut" style={{ background: sum ? `conic-gradient(#609be0 0% ${b}%, #9683dc ${b}% ${b + t}%, #eda85b ${b + t}% 100%)` : "#e8edf1" }}><div><strong>{number(total, 1)}<small>h</small></strong><span>horas alocadas</span></div></div><span className="donut-side-label"><i className="dot blue" /> Capacidade<br />em movimento</span></div>; }
function DemandTable({ demands, data, timezone, displayName, showDetails, onOpen, detailed }: { demands: Demand[]; data: State; timezone: string; displayName: (id: string) => string; showDetails: boolean; onOpen: (d: Demand) => void; detailed?: boolean }) { return <div className="table-scroll"><table className="demand-table"><thead><tr><th>DEMANDA</th><th>TIPO</th><th>EXECUÇÃO</th><th>ALOCADOS</th>{detailed && <th>PRIORIDADE</th>}<th>STATUS</th><th /></tr></thead><tbody>{demands.map(d => { const ids = Array.from(new Set(d.allocations.map(a => a.employeeId))); return <tr key={d.id} className="clickable-row" onClick={() => onOpen(d)}><td><strong className="demand-name">{d.title}</strong><small>{d.code}{showDetails && d.project ? ` · ${d.project}` : ""}</small></td><td><span className={`type-badge ${d.type.toLowerCase()}`}><i />{d.type}</span></td><td><strong>{dateLabel(d.date)}</strong><small>{timeLabel(d.start, timezone)} — {timeLabel(d.end, timezone)}{dateAt(d.end, timezone) !== dateAt(d.start, timezone) ? " +1" : ""}</small></td><td><div className="allocation-avatars">{ids.slice(0, 3).map(id => <span className={`avatar mini-avatar color-${data.employees.findIndex(e => e.id === id) % 5}`} key={id} title={displayName(id)}>{initials(displayName(id))}</span>)}{!ids.length ? <span className="unassigned">A definir</span> : <span className={`allocation-count ${ids.length < d.required ? "short" : ""}`}>{ids.length}/{d.required}</span>}</div></td>{detailed && <td><span className={`priority ${d.priority}`}><i />{PRIORITY[d.priority]}</span></td>}<td><span className={`badge ${d.status}`}>{STATUS[d.status]}</span></td><td><ChevronRight size={15} className="muted-icon" /></td></tr>; })}</tbody></table>{!demands.length && <Empty icon={FileText} title="Tudo pronto para planejar" text="Nenhuma demanda encontrada com estes filtros e período." />}</div>; }
function Empty({ icon: Icon, title, text }: { icon: typeof Users; title: string; text: string }) { return <div className="empty-state"><span><Icon size={25} /></span><strong>{title}</strong><p>{text}</p></div>; }
type CalendarCell = ReturnType<typeof buildCalendar>[number];
function CalendarGrid({ data, cells, start, end, mode, displayName, onCell, typeFilter, statusFilter }: { data: State; typeFilter: string; statusFilter: string; cells: CalendarCell[]; start: string; end: string; mode: string; displayName: (id: string) => string; onCell: (employeeId: string, date: string, hour: number, demandId?: string) => void }) { const days = daysBetween(start, end); const cellMap = useMemo(() => new Map(cells.map(c => [`${c.employeeId}|${c.date}|${c.hour}`, c])), [cells]); const width = mode === "day" ? 42 : mode === "month" ? 9 : 12; const dayWidth = width * 24; const chgCapacity = useMemo(() => typeFilter === "CHG" ? typeCapacity(data, start, end, "CHG") : null, [data, start, end, typeFilter]); return <div className="calendar-scroll"><div className="calendar-grid" style={{ width: `${188 + days.length * dayWidth}px` }}><div className="calendar-header"><div className="calendar-person-header">COLABORADORES <span>{data.employees.filter(e => e.active).length}</span></div>{days.map(d => <div className={`calendar-date ${[0, 6].includes(new Date(d + "T12:00:00").getDay()) ? "weekend" : ""}`} style={{ width: dayWidth }} key={d}><strong>{dateLabel(d, { weekday: "short", day: "2-digit", month: "short" })}</strong><div className="hour-labels">{Array.from({ length: 24 }, (_, h) => <span key={h} style={{ width }} title={`${h}h`}>{(mode === "day" || h % 6 === 0) ? String(h).padStart(2, "0") : ""}</span>)}</div></div>)}</div>{data.employees.filter(e => e.active).map((e, index) => <div className="calendar-row" key={e.id}><div className="calendar-person"><span className={`avatar color-${index % 5}`}>{initials(displayName(e.id))}</span><div><strong>{displayName(e.id)}</strong><small>{e.journey === "night" ? "Noturno" : e.journey === "day" ? "Diurno" : "Personalizada"} · {e.startTime}–{e.endTime}</small></div></div>{days.map(d => <div className="calendar-day" key={d} style={{ width: dayWidth }}>{Array.from({ length: 24 }, (_, hour) => { const c = cellMap.get(`${e.id}|${d}|${hour}`); const prev = cellMap.get(`${e.id}|${d}|${hour - 1}`); const next = cellMap.get(`${e.id}|${d}|${hour + 1}`); const hourStart = Date.parse(zoned(d, `${String(hour).padStart(2, "0")}:00`, data.settings.timezone)); const hourEnd = Date.parse(zoned(hour === 23 ? addDays(d, 1) : d, `${String((hour + 1) % 24).padStart(2, "0")}:00`, data.settings.timezone)); const eligibleWindows = c?.status === "potential" ? chgCapacity?.potentialAlternatives : chgCapacity?.windows; const eligibleMinutes = eligibleWindows?.filter(window => window.employeeId === e.id).reduce((sum, window) => sum + Math.max(0, Math.min(hourEnd, Date.parse(window.end)) - Math.max(hourStart, Date.parse(window.start))) / 60000, 0) || 0; const outsideCHG = typeFilter === "CHG" && ["free", "potential"].includes(c?.status || "") && eligibleMinutes === 0; const cellStatus = outsideCHG ? "off" : c?.status || "off"; const cellLabel = outsideCHG ? `Fora da janela CHG ${data.settings.nightStart}–${data.settings.nightEnd} ou sem jornada elegível nesta faixa` : `${c?.label || "Fora da jornada"}${typeFilter === "CHG" && eligibleMinutes > 0 ? ` · ${number(eligibleMinutes, 1)} min ${c?.status === "potential" ? "potenciais, sujeitos à aprovação" : "de capacidade CHG confirmada"}` : ""}`; const linked = data.demands.find(v => v.id === c?.demandId); const muted = linked && ((typeFilter && linked.type !== typeFilter) || (statusFilter && linked.status !== statusFilter)); const labelStart = c?.demandId && c.demandId !== prev?.demandId; return <button key={hour} className={`hour-cell slot-${muted ? "other" : cellStatus} ${c?.demandId && c.demandId === prev?.demandId ? "joins-left" : ""} ${c?.demandId && c.demandId === next?.demandId ? "joins-right" : ""}`} style={{ width }} title={`${displayName(e.id)} · ${dateLabel(d)} · ${String(hour).padStart(2, "0")}:00–${String((hour + 1) % 24).padStart(2, "0")}:00\n${cellLabel}${c?.returnAt ? `\nRetorno permitido: ${new Date(c.returnAt).toLocaleString("pt-BR", { timeZone: data.settings.timezone })}` : ""}`} aria-label={`${displayName(e.id)}, ${d} às ${hour}h, ${cellLabel}`} onClick={() => onCell(e.id, d, hour, c?.demandId)}>{labelStart && <span>{muted ? "Alocado" : linked?.code || c?.label}</span>}</button>; })}</div>)}</div>)}</div></div>; }
function ModalShell({ title, subtitle, onClose, wide, children }: { title: string; subtitle: string; onClose: () => void; wide?: boolean; children: React.ReactNode }) {
  const dialog = useRef<HTMLElement>(null);
  useEffect(() => {
    const previousFocus = document.activeElement as HTMLElement | null;
    const key = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
      if (event.key !== "Tab" || !dialog.current) return;
      const focusable = Array.from(dialog.current.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex="0"]')).filter(element => element.offsetParent !== null);
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
    };
    document.addEventListener("keydown", key);
    const prior = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.removeEventListener("keydown", key); document.body.style.overflow = prior; previousFocus?.focus(); };
  }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section ref={dialog} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide ? "wide" : ""}`}><div className="modal-heading"><div><h2>{title}</h2><p>{subtitle}</p></div><button autoFocus className="icon-button" aria-label="Fechar janela" onClick={onClose}><X size={20} /></button></div><div className="modal-body">{children}</div></section></div>;
}
function Simulator({ data, start, displayName, writable, onCreate }: { data: State; start: string; displayName: (id: string) => string; writable: boolean; onCreate: (proposal: Partial<Demand>) => void }) { const [type, setType] = useState<DemandType>("BSIM"); const [date, setDate] = useState(start); const [time, setTime] = useState("09:00"); const [duration, setDuration] = useState(2); const [required, setRequired] = useState(1); const [result, setResult] = useState<ReturnType<typeof simulate> | null>(null); const [proposal, setProposal] = useState<{ type: DemandType; start: string; end: string; required: number } | null>(null); const [error, setError] = useState(""); const run = () => { try { if (!(duration > 0 && duration <= 72) || !(required > 0)) throw new Error("Informe duração e quantidade válidas."); const begin = zoned(date, time, data.settings.timezone); const p = { type, start: begin, end: new Date(new Date(begin).getTime() + duration * 3600000).toISOString(), required }; setProposal(p); setResult(simulate(data, p)); setError(""); } catch (e) { setError(e instanceof Error ? e.message : "Não foi possível simular."); } }; return <><div className="simulation-intro"><span><WandSparkles size={21} /></span><div><strong>Teste possibilidades. Decida com confiança.</strong><p>O resultado considera jornadas aprovadas, alocações, ausências e interjornada. Nenhum dado oficial é alterado.</p></div></div><div className="form-grid simulator-fields"><Field label="Tipo de demanda"><select value={type} onChange={e => { setType(e.target.value as DemandType); if (e.target.value === "CHG") setTime(data.settings.nightStart); setResult(null); }}><option>BSIM</option><option>TSD</option><option>CHG</option></select></Field><Field label="Data pretendida"><input type="date" value={date} onChange={e => { setDate(e.target.value); setResult(null); }} /></Field><Field label="Horário de início"><input type="time" value={time} onChange={e => { setTime(e.target.value); setResult(null); }} /></Field><Field label="Duração (horas)"><input type="number" min="0.25" max="72" step="0.25" value={duration} onChange={e => { setDuration(+e.target.value); setResult(null); }} /></Field><Field label="Pessoas necessárias"><input type="number" min="1" max="100" value={required} onChange={e => { setRequired(+e.target.value); setResult(null); }} /></Field><button className="button primary simulate-button" onClick={run}><Sparkles size={16} /> Analisar capacidade</button></div>{error && <div className="form-error">{error}</div>}{result && proposal && <div className="simulation-results"><div className={`simulation-verdict ${result.canAbsorb && !result.requiresExtra ? "healthy" : "warning"}`}><span>{result.canAbsorb && !result.requiresExtra ? <CheckCircle2 size={24} /> : <AlertTriangle size={24} />}</span><div><strong>{result.canAbsorb && !result.requiresExtra ? "A demanda pode ser absorvida integralmente." : result.potential.length >= required ? "Há potencial, condicionado à aprovação de escala." : "Não há capacidade confirmada para esta janela."}</strong><p>{result.eligible.length} elegível(is) em escala confirmada · {result.potential.length} com potencial extraordinário</p></div></div><div className="simulation-stats"><div><strong>{number(result.occupancyAfter, 1)}%</strong><span>Ocupação após inclusão</span></div><div><strong>{number(duration * required, 1)}h</strong><span>Consumo operacional</span></div><div><strong>{result.requiresExtra ? "Necessária" : "Dispensada"}</strong><span>Ativação extraordinária</span></div></div><div className="simulation-columns"><div><h3>Colaboradores elegíveis</h3>{result.eligible.length ? result.eligible.map((e, i) => <div className="eligible-person" key={e.id}><span className={`avatar color-${i % 5}`}>{initials(displayName(e.id))}</span><span><strong>{displayName(e.id)}</strong><small>Escala confirmada</small></span><CheckCircle2 size={16} /></div>) : <p className="muted-copy">Sem cobertura confirmada integral neste horário.</p>}{result.potential.length > 0 && <><h4>Potencial extraordinário</h4>{result.potential.map(e => <div className="potential-person" key={e.id}><Moon size={14} /><span>{displayName(e.id)}</span><small>Requer escala aprovada</small></div>)}</>}</div><div><h3>Impactos e validações</h3>{result.issues.length > 0 ? result.issues.map((issue, i) => <p className="simulation-issue" key={i}><AlertTriangle size={14} />{typeof issue === "string" ? issue : issue.message}</p>) : <p className="simulation-success"><CheckCircle2 size={15} /> Nenhum conflito identificado para os elegíveis.</p>}{result.impactNextDay.map((impact, i) => <p className="simulation-issue" key={i}><Clock3 size={14} />{impact}</p>)}</div></div>{result.alternatives.length > 0 && <div className="simulation-alternatives"><h3>Janelas alternativas</h3>{result.alternatives.slice(0, 5).map(a => <button key={a.start} onClick={() => { setDate(dateAt(a.start, data.settings.timezone)); setTime(timeLabel(a.start, data.settings.timezone)); setResult(null); }}><CalendarDays size={15} /><span>{dateLabel(dateAt(a.start, data.settings.timezone))} · {timeLabel(a.start, data.settings.timezone)}–{timeLabel(a.end, data.settings.timezone)}</span><small>{a.eligibleCount} elegíveis</small><ArrowRight size={14} /></button>)}</div>}<div className="form-actions"><span className="readonly-note"><ShieldCheck size={14} /> Simulação não altera os dados oficiais</span>{writable && <button className="button primary" onClick={() => onCreate({ ...proposal, date: dateAt(proposal.start, data.settings.timezone), required, status: "planning", allocations: result.eligible.slice(0, required).map(e => ({ id: crypto.randomUUID(), employeeId: e.id, start: proposal.start, end: proposal.end })) })}><Plus size={16} /> Criar demanda</button>}</div></div>}</>; }









